use super::CodeGenerator;
use proc_macro2::{Span, TokenStream};
use quote::quote;
use riscv_instruction_schema::{
    AssemblySyntax, ISABase, ISAExtension, ImmediateKind, Instruction, Operand, OperandKind,
    OperandUsage, RegisterBank, RegisterRole,
};
use std::collections::{HashMap, HashSet};
use syn::Ident;

/// Replace `{name_enc}` capture groups with `{name}` in an asm pattern string,
/// so that pattern matching uses bare operand names instead of the `_enc`-suffixed
/// variable names generated by the assembly syntax code blocks.
fn strip_enc_suffixes_from_pattern(pattern: &str) -> String {
    let mut result = String::with_capacity(pattern.len());
    let mut rest = pattern;
    while let Some(open) = rest.find('{') {
        result.push_str(&rest[..open + 1]);
        rest = &rest[open + 1..];
        if let Some(close) = rest.find('}') {
            let name = &rest[..close];
            let stripped = name.strip_suffix("_enc").unwrap_or(name);
            result.push_str(stripped);
            result.push('}');
            rest = &rest[close + 1..];
        }
    }
    result.push_str(rest);
    result
}

impl CodeGenerator {
    fn generate_attribute_token(&self, assembly_syntax: &AssemblySyntax) -> TokenStream {
        match assembly_syntax {
            AssemblySyntax::RustCode(code) => {
                let code_str = code.as_str();
                quote! { #[asm_code(#code_str)] }
            }
            AssemblySyntax::Format(format_str) => quote! { #[asm(#format_str)] },
        }
    }

    fn generate_instruction_fields(
        &self,
        instruction: &Instruction,
        isa_base: &ISABase,
    ) -> Vec<TokenStream> {
        instruction
            .operands
            .iter()
            .map(|operand| {
                let operand_name = Ident::new(&operand.name, Span::call_site());
                let operand_runtime_type =
                    self.operand_to_typed_struct(operand, isa_base, instruction);
                let field_type: TokenStream = operand_runtime_type
                    .parse()
                    .expect("Failed to parse operand type string");
                quote! { pub #operand_name: #field_type }
            })
            .collect()
    }

    fn generate_sequence_attribute(&self, instruction: &Instruction) -> Option<TokenStream> {
        let mut args = Vec::new();

        if let Some(memory_base) = instruction.memory_base_operand_name() {
            args.push(quote! { memory_base = #memory_base });
        }
        if let Some(memory_base_fixed) = instruction.memory_base_fixed_register() {
            args.push(quote! { memory_base_fixed = #memory_base_fixed });
        }
        if let Some(csr) = instruction.writable_csr_operand_name() {
            args.push(quote! { csr = #csr });
        }
        if let Some(csr_source) = instruction.csr_source_register_operand_name() {
            args.push(quote! { csr_source = #csr_source });
        }
        if let Some(pc_relative) = instruction.pc_relative_target_operand_name() {
            args.push(quote! { pc_relative = #pc_relative });
        }
        if let Some(pc_relative_fixed) = instruction.pc_relative_target_fixed_register() {
            args.push(quote! { pc_relative_fixed = #pc_relative_fixed });
        }
        if instruction.uses_floating_point_registers() {
            args.push(quote! { touches_floating_point = true });
        }

        if args.is_empty() {
            None
        } else {
            Some(quote! { #[sequence(#(#args),*)] })
        }
    }

    fn numeric_operand_fields(&self, instruction: &Instruction) -> Vec<Ident> {
        instruction
            .operands
            .iter()
            .filter(|operand| operand.supports_numeric_mutation(instruction))
            .map(|operand| Ident::new(&operand.name, Span::call_site()))
            .collect()
    }

    fn generate_numeric_mutation_impl(
        &self,
        struct_ident: &Ident,
        instruction: &Instruction,
    ) -> TokenStream {
        let numeric_fields = self.numeric_operand_fields(instruction);

        if numeric_fields.is_empty() {
            return quote! {
                impl NumericOperandMutation for #struct_ident {
                    fn mutate_numeric_operands<R: rand::Rng>(
                        &mut self,
                        _rng: &mut R,
                        _config: &RandomConfig,
                    ) -> bool {
                        false
                    }
                }
            };
        }

        quote! {
            impl NumericOperandMutation for #struct_ident {
                fn mutate_numeric_operands<R: rand::Rng>(
                    &mut self,
                    rng: &mut R,
                    config: &RandomConfig,
                ) -> bool {
                    let mut changed = false;
                    #(changed |= NumericOperandMutation::mutate_numeric_operands(&mut self.#numeric_fields, rng, config);)*
                    changed
                }
            }
        }
    }

    fn runtime_operand_usage_tokens(&self, usage: OperandUsage) -> TokenStream {
        match usage {
            OperandUsage::Destination => {
                quote!(::riscv_instruction_types::RuntimeOperandUsage::Destination)
            }
            OperandUsage::Source => quote!(::riscv_instruction_types::RuntimeOperandUsage::Source),
            OperandUsage::MemoryBase => {
                quote!(::riscv_instruction_types::RuntimeOperandUsage::MemoryBase)
            }
            OperandUsage::MemoryOffset => {
                quote!(::riscv_instruction_types::RuntimeOperandUsage::MemoryOffset)
            }
            OperandUsage::CsrAddress => {
                quote!(::riscv_instruction_types::RuntimeOperandUsage::CsrAddress)
            }
            OperandUsage::Aggregate => {
                quote!(::riscv_instruction_types::RuntimeOperandUsage::Aggregate)
            }
            OperandUsage::SyntaxOnly => {
                quote!(::riscv_instruction_types::RuntimeOperandUsage::SyntaxOnly)
            }
        }
    }

    fn runtime_register_role_tokens(&self, role: RegisterRole) -> TokenStream {
        match role {
            RegisterRole::Plain => {
                quote!(::riscv_instruction_types::RuntimeRegisterRole::Plain)
            }
            RegisterRole::MemoryBase => {
                quote!(::riscv_instruction_types::RuntimeRegisterRole::MemoryBase)
            }
            RegisterRole::SavedAlias => {
                quote!(::riscv_instruction_types::RuntimeRegisterRole::SavedAlias)
            }
        }
    }

    fn fixed_integer_register_number(&self, value: &str) -> Option<u8> {
        let normalized = value.trim().to_ascii_lowercase();
        let number = match normalized.as_str() {
            "zero" | "x0" => 0,
            "ra" | "x1" => 1,
            "sp" | "x2" => 2,
            "gp" | "x3" => 3,
            "tp" | "x4" => 4,
            "t0" | "x5" => 5,
            "t1" | "x6" => 6,
            "t2" | "x7" => 7,
            "s0" | "fp" | "x8" => 8,
            "s1" | "x9" => 9,
            "a0" | "x10" => 10,
            "a1" | "x11" => 11,
            "a2" | "x12" => 12,
            "a3" | "x13" => 13,
            "a4" | "x14" => 14,
            "a5" | "x15" => 15,
            "a6" | "x16" => 16,
            "a7" | "x17" => 17,
            "s2" | "x18" => 18,
            "s3" | "x19" => 19,
            "s4" | "x20" => 20,
            "s5" | "x21" => 21,
            "s6" | "x22" => 22,
            "s7" | "x23" => 23,
            "s8" | "x24" => 24,
            "s9" | "x25" => 25,
            "s10" | "x26" => 26,
            "s11" | "x27" => 27,
            "t3" | "x28" => 28,
            "t4" | "x29" => 29,
            "t5" | "x30" => 30,
            "t6" | "x31" => 31,
            _ => return None,
        };
        Some(number)
    }

    fn generate_runtime_operand_access_impl(
        &self,
        struct_ident: &Ident,
        instruction: &Instruction,
        isa_base: &ISABase,
    ) -> TokenStream {
        let register_pushes = instruction
            .operands
            .iter()
            .filter_map(|operand| {
                let semantics = operand.register_semantics(*isa_base, instruction)?;
                let field_ident = Ident::new(&operand.name, Span::call_site());
                let usage = self.runtime_operand_usage_tokens(operand.usage(instruction));
                let role = self.runtime_register_role_tokens(semantics.role);
                let operand_name = operand.name.clone();
                Some(quote! {
                    registers.push(::riscv_instruction_types::RuntimeRegisterOperand {
                        name: #operand_name,
                        usage: #usage,
                        role: #role,
                        register: ::riscv_instruction_types::runtime_register(self.#field_ident),
                    });
                })
            })
            .collect::<Vec<_>>();

        let register_set_arms = instruction
            .operands
            .iter()
            .filter_map(|operand| {
                operand.register_semantics(*isa_base, instruction)?;
                let field_ident = Ident::new(&operand.name, Span::call_site());
                let operand_name = operand.name.clone();
                Some(quote! {
                    #operand_name => ::riscv_instruction_types::set_register_from_runtime_assignment(
                        &mut self.#field_ident,
                        #operand_name,
                        register,
                    )
                })
            })
            .collect::<Vec<_>>();

        let memory_operands_impl = if let Some(memory_access) = instruction.memory_access.as_ref() {
            let base_name_literal = match memory_access.base_register_operand.as_deref() {
                Some(name) => quote! { Some(#name) },
                None => quote! { None },
            };
            let offset_name_literal = match memory_access.offset_operand.as_deref() {
                Some(name) => quote! { Some(#name) },
                None => quote! { None },
            };
            let base_register_init = if let Some(base_name) = &memory_access.base_register_operand {
                let field_ident = Ident::new(base_name, Span::call_site());
                let operand = instruction
                    .operands
                    .iter()
                    .find(|operand| operand.name == *base_name)
                    .unwrap_or_else(|| {
                        panic!(
                            "memory base operand `{}` missing from instruction `{}`",
                            base_name, instruction.name
                        )
                    });
                let semantics = operand
                    .register_semantics(*isa_base, instruction)
                    .unwrap_or_else(|| {
                        panic!(
                            "memory base operand `{}` in instruction `{}` is not a register",
                            base_name, instruction.name
                        )
                    });
                let usage = self.runtime_operand_usage_tokens(operand.usage(instruction));
                let role = self.runtime_register_role_tokens(semantics.role);
                let base_name_text = base_name.clone();
                quote! {
                    let base_register = Some(::riscv_instruction_types::RuntimeRegisterOperand {
                        name: #base_name_text,
                        usage: #usage,
                        role: #role,
                        register: ::riscv_instruction_types::runtime_register(self.#field_ident),
                    });
                }
            } else {
                quote! {
                    let base_register = None;
                }
            };

            let fixed_base_register_init = if let Some(fixed_base) =
                &memory_access.base_register_fixed
            {
                if fixed_base.eq_ignore_ascii_case("pc") {
                    quote! {
                        let fixed_base = Some(
                            ::riscv_instruction_types::RuntimeMemoryBase::ProgramCounter
                        );
                    }
                } else {
                    let number = self
                        .fixed_integer_register_number(fixed_base)
                        .unwrap_or_else(|| {
                            panic!(
                                "unsupported fixed memory base register `{}` in instruction `{}`",
                                fixed_base, instruction.name
                            )
                        });
                    quote! {
                        let fixed_base = Some(
                            ::riscv_instruction_types::RuntimeMemoryBase::Register(
                                ::riscv_instruction_types::runtime_fixed_integer_register(#number)
                            )
                        );
                    }
                }
            } else {
                quote! {
                    let fixed_base = None;
                }
            };

            let offset_value_init = if let Some(offset_name) = &memory_access.offset_operand {
                let offset_ident = Ident::new(offset_name, Span::call_site());
                let operand = instruction
                    .operands
                    .iter()
                    .find(|operand| operand.name == *offset_name)
                    .unwrap_or_else(|| {
                        panic!(
                            "memory offset operand `{}` missing from instruction `{}`",
                            offset_name, instruction.name
                        )
                    });
                let value_expr = if operand.uses_inline_boolean_value(instruction) {
                    quote! { if self.#offset_ident { 1 } else { 0 } }
                } else {
                    quote! { self.#offset_ident.get() as i64 }
                };
                quote! {
                    let offset_value = Some(#value_expr);
                }
            } else {
                quote! {
                    let offset_value = None;
                }
            };

            let set_base_stmt = if let Some(base_name) = &memory_access.base_register_operand {
                let field_ident = Ident::new(base_name, Span::call_site());
                let base_name_text = base_name.clone();
                quote! {
                    if let Some(base_register) = patch.base_register {
                        changed |= ::riscv_instruction_types::set_register_from_runtime_assignment(
                            &mut self.#field_ident,
                            #base_name_text,
                            base_register,
                        )?;
                    }
                }
            } else if memory_access.base_register_fixed.is_some() {
                quote! {
                    if patch.base_register.is_some() {
                        return Err(::riscv_instruction_types::OperandAccessError::new(
                            "memory operand #0",
                            "base register is fixed by the ISA form and cannot be rewritten",
                        ));
                    }
                }
            } else {
                quote! {
                    if patch.base_register.is_some() {
                        return Err(::riscv_instruction_types::OperandAccessError::new(
                            "memory operand #0",
                            "instruction does not expose a mutable memory base register",
                        ));
                    }
                }
            };

            let set_offset_stmt = if let Some(offset_name) = &memory_access.offset_operand {
                let offset_ident = Ident::new(offset_name, Span::call_site());
                let operand = instruction
                    .operands
                    .iter()
                    .find(|operand| operand.name == *offset_name)
                    .unwrap_or_else(|| {
                        panic!(
                            "memory offset operand `{}` missing from instruction `{}`",
                            offset_name, instruction.name
                        )
                    });
                let offset_name_text = offset_name.clone();
                let setter = if operand.uses_inline_boolean_value(instruction) {
                    quote! {
                        changed |= ::riscv_instruction_types::set_bool_operand_from_i64(
                            &mut self.#offset_ident,
                            #offset_name_text,
                            value,
                        )?;
                    }
                } else {
                    match operand.runtime_immediate_kind(instruction) {
                        Some(
                            ImmediateKind::Signed
                            | ImmediateKind::CompressedSigned
                            | ImmediateKind::LinearBranch
                            | ImmediateKind::LinearCompressedBranch
                            | ImmediateKind::LinearJalr
                            | ImmediateKind::VectorSigned,
                        ) => quote! {
                            changed |= ::riscv_instruction_types::set_validated_i32_operand_from_i64(
                                &mut self.#offset_ident,
                                #offset_name_text,
                                value,
                            )?;
                        },
                        Some(
                            ImmediateKind::Unsigned
                            | ImmediateKind::ShiftAmount
                            | ImmediateKind::CompressedUnsigned
                            | ImmediateKind::VectorUnsigned,
                        ) => quote! {
                            changed |= ::riscv_instruction_types::set_validated_u32_operand_from_i64(
                                &mut self.#offset_ident,
                                #offset_name_text,
                                value,
                            )?;
                        },
                        Some(
                            ImmediateKind::Float16
                            | ImmediateKind::Float32
                            | ImmediateKind::Float64
                            | ImmediateKind::Float128,
                        ) => panic!(
                            "memory offset operand `{}` unexpectedly resolved to floating immediate kind",
                            offset_name
                        ),
                        None => panic!(
                            "memory offset operand `{}` does not resolve to a runtime immediate kind",
                            offset_name
                        ),
                    }
                };
                quote! {
                    if let Some(value) = patch.offset_value {
                        #setter
                    }
                }
            } else {
                quote! {
                    if patch.offset_value.is_some() {
                        return Err(::riscv_instruction_types::OperandAccessError::new(
                            "memory operand #0",
                            "instruction does not expose a mutable memory offset operand",
                        ));
                    }
                }
            };

            quote! {
                fn memory_operands(&self) -> Vec<::riscv_instruction_types::RuntimeMemoryOperand> {
                    #base_register_init
                    #fixed_base_register_init
                    #offset_value_init
                    vec![::riscv_instruction_types::RuntimeMemoryOperand {
                        index: 0,
                        base_register_operand_name: #base_name_literal,
                        base_register,
                        fixed_base,
                        offset_operand_name: #offset_name_literal,
                        offset_value,
                    }]
                }

                fn set_memory_operand(
                    &mut self,
                    index: usize,
                    patch: ::riscv_instruction_types::RuntimeMemoryOperandPatch,
                ) -> Result<bool, ::riscv_instruction_types::OperandAccessError> {
                    if index != 0 {
                        return Err(::riscv_instruction_types::OperandAccessError::missing_memory_operand(index));
                    }

                    let mut changed = false;
                    #set_base_stmt
                    #set_offset_stmt
                    Ok(changed)
                }
            }
        } else {
            quote! {
                fn memory_operands(&self) -> Vec<::riscv_instruction_types::RuntimeMemoryOperand> {
                    Vec::new()
                }

                fn set_memory_operand(
                    &mut self,
                    index: usize,
                    _patch: ::riscv_instruction_types::RuntimeMemoryOperandPatch,
                ) -> Result<bool, ::riscv_instruction_types::OperandAccessError> {
                    Err(::riscv_instruction_types::OperandAccessError::missing_memory_operand(index))
                }
            }
        };

        let register_operands_impl = if register_pushes.is_empty() {
            quote! {
                fn register_operands(&self) -> Vec<::riscv_instruction_types::RuntimeRegisterOperand> {
                    Vec::new()
                }
            }
        } else {
            quote! {
                fn register_operands(&self) -> Vec<::riscv_instruction_types::RuntimeRegisterOperand> {
                    let mut registers = Vec::new();
                    #(#register_pushes)*
                    registers
                }
            }
        };

        let set_register_impl = if register_set_arms.is_empty() {
            quote! {
                fn set_register_operand(
                    &mut self,
                    operand_name: &str,
                    _register: ::riscv_instruction_types::RuntimeRegisterAssignment,
                ) -> Result<bool, ::riscv_instruction_types::OperandAccessError> {
                    Err(::riscv_instruction_types::OperandAccessError::missing_register_operand(operand_name))
                }
            }
        } else {
            quote! {
                fn set_register_operand(
                    &mut self,
                    operand_name: &str,
                    register: ::riscv_instruction_types::RuntimeRegisterAssignment,
                ) -> Result<bool, ::riscv_instruction_types::OperandAccessError> {
                    match operand_name {
                        #(#register_set_arms),*,
                        _ => Err(::riscv_instruction_types::OperandAccessError::missing_register_operand(operand_name)),
                    }
                }
            }
        };

        quote! {
            impl ::riscv_instruction_types::RuntimeOperandAccess for #struct_ident {
                #register_operands_impl
                #memory_operands_impl
                #set_register_impl
            }
        }
    }

    fn generate_memory_access_impl(
        &self,
        struct_ident: &Ident,
        instruction: &Instruction,
    ) -> Option<TokenStream> {
        let memory_access = instruction.memory_access.as_ref()?;
        let none_offset_method = quote! {
            fn offset_operand_value(&self) -> Option<i64> {
                None
            }
        };

        let offset_method = if let Some(offset_operand) = &memory_access.offset_operand {
            let offset_ident = Ident::new(offset_operand, Span::call_site());
            if let Some(operand) = instruction
                .operands
                .iter()
                .find(|operand| operand.name == *offset_operand)
            {
                let value_expr = if operand.uses_inline_boolean_value(instruction) {
                    quote! { self.#offset_ident as i64 }
                } else {
                    quote! { self.#offset_ident.get() as i64 }
                };

                quote! {
                    fn offset_operand_value(&self) -> Option<i64> {
                        Some(#value_expr)
                    }
                }
            } else {
                none_offset_method.clone()
            }
        } else {
            none_offset_method
        };

        Some(quote! {
            impl MemoryAccessInstruction for #struct_ident {
                #offset_method
            }
        })
    }

    fn normalize_rust_code(&self, code: &str) -> String {
        code.split_whitespace().collect::<Vec<_>>().join(" ")
    }

    fn extract_format_string_from_rust_code(&self, code: &str) -> Option<String> {
        let marker = "format!(\"";
        let start = code.find(marker)? + marker.len();
        let rest = &code[start..];
        let mut escaped = false;

        for (idx, ch) in rest.char_indices() {
            if escaped {
                escaped = false;
                continue;
            }

            match ch {
                '\\' => escaped = true,
                '"' => return Some(rest[..idx].to_string()),
                _ => {}
            }
        }

        None
    }

    fn extract_placeholder_names(&self, pattern: &str) -> HashSet<String> {
        let mut placeholders = HashSet::new();
        let mut rest = pattern;

        while let Some(open) = rest.find('{') {
            let after_open = &rest[open + 1..];
            let Some(close) = after_open.find('}') else {
                break;
            };
            let placeholder = after_open[..close].trim();
            if !placeholder.is_empty() && !placeholder.contains(':') {
                placeholders.insert(placeholder.to_string());
            }
            rest = &after_open[close + 1..];
        }

        placeholders
    }

    fn hidden_operand_default_text(
        &self,
        operand: &Operand,
        instruction: &Instruction,
    ) -> Option<String> {
        match &operand.kind {
            OperandKind::Register(spec) => Some(match spec.bank {
                RegisterBank::Integer => "x0".to_string(),
                RegisterBank::FloatingPoint => "f0".to_string(),
                RegisterBank::Vector => "v0".to_string(),
            }),
            OperandKind::Immediate(spec) => Some(
                operand
                    .runtime_immediate_kind(instruction)
                    .and_then(|kind| kind.fixed_value())
                    .map(|value| value.to_string())
                    .unwrap_or_else(|| match spec.kind {
                        _ => "0".to_string(),
                    }),
            ),
            OperandKind::RoundMode => Some("dyn".to_string()),
            OperandKind::FenceMode => Some("iorw".to_string()),
            _ => None,
        }
    }

    fn generate_standard_operand_bindings(
        &self,
        struct_ident: &Ident,
        instruction: &Instruction,
        isa_base: &ISABase,
        pattern: &str,
    ) -> Vec<TokenStream> {
        let placeholders = self.extract_placeholder_names(pattern);
        instruction
            .operands
            .iter()
            .map(|operand| {
                let operand_ident = Ident::new(&operand.name, Span::call_site());
                let operand_type: TokenStream = self
                    .operand_to_typed_struct(operand, isa_base, instruction)
                    .parse()
                    .expect("Failed to parse operand type string");
                let operand_name = operand.name.clone();
                if placeholders.contains(&operand.name) {
                    quote! {
                        let #operand_ident = {
                            let text = captures.remove(#operand_name).ok_or_else(|| {
                                AsmParseError::syntax_mismatch(
                                    stringify!(#struct_ident),
                                    format!("missing operand `{}`", #operand_name),
                                )
                            })?;
                            <#operand_type as AsmDecode>::decode_asm(&text)
                                .map_err(|err| err.with_context(format!("while parsing operand `{}`", #operand_name)))?
                        };
                    }
                } else {
                    let default_text = self.hidden_operand_default_text(operand, instruction)
                        .unwrap_or_else(|| {
                            panic!(
                                "unsupported hidden asm operand `{}` for instruction {}",
                                operand.name, instruction.name
                            )
                        });
                    quote! {
                        let #operand_ident =
                            <#operand_type as AsmDecode>::decode_asm(#default_text)
                                .map_err(|err| err.with_context(format!(
                                    "while synthesizing hidden operand `{}`",
                                    #operand_name,
                                )))?;
                    }
                }
            })
            .collect()
    }

    fn generate_struct_from_str_impl(
        &self,
        struct_ident: &Ident,
        instruction: &Instruction,
        isa_base: &ISABase,
    ) -> TokenStream {
        let field_idents: Vec<_> = instruction
            .operands
            .iter()
            .map(|operand| Ident::new(&operand.name, Span::call_site()))
            .collect();
        let construct = if instruction.operands.is_empty() {
            quote! { Self }
        } else {
            quote! { Self { #(#field_idents),* } }
        };

        let body = match &instruction.assembly_syntax {
            AssemblySyntax::Format(pattern) => {
                let bindings = self.generate_standard_operand_bindings(
                    struct_ident,
                    instruction,
                    isa_base,
                    pattern,
                );
                quote! {
                    let mut captures = parse_asm_pattern(stringify!(#struct_ident), #pattern, s)?;
                    #(#bindings)*
                    Ok(#construct)
                }
            }
            AssemblySyntax::RustCode(code) => {
                let normalized = self.normalize_rust_code(code);
                if normalized.contains("let vm_suffix = if *vm { \"\" } else { \", v0.t\" };") {
                    let format_str = self
                        .extract_format_string_from_rust_code(code)
                        .expect("vm_suffix asm_code should contain format! string");
                    let base_pattern = strip_enc_suffixes_from_pattern(
                        &format_str.replace("{vm_suffix}", ""),
                    );
                    let bindings: Vec<_> = instruction
                        .operands
                        .iter()
                        .map(|operand| {
                            let operand_ident = Ident::new(&operand.name, Span::call_site());
                            let operand_name = operand.name.clone();
                            if operand.name == "vm" {
                                quote! { let #operand_ident = vm; }
                            } else {
                                let operand_type: TokenStream = self
                                    .operand_to_typed_struct(operand, isa_base, instruction)
                                    .parse()
                                    .expect("Failed to parse operand type string");
                                quote! {
                                    let #operand_ident = {
                                        let text = captures.remove(#operand_name).ok_or_else(|| {
                                            AsmParseError::syntax_mismatch(
                                                stringify!(#struct_ident),
                                                format!("missing operand `{}`", #operand_name),
                                            )
                                        })?;
                                        <#operand_type as AsmDecode>::decode_asm(&text)
                                            .map_err(|err| err.with_context(format!("while parsing operand `{}`", #operand_name)))?
                                    };
                                }
                            }
                        })
                        .collect();
                    quote! {
                        let trimmed = s.trim();
                        let (body, vm) = if let Some(prefix) = trimmed.strip_suffix(", v0.t") {
                            (prefix, false)
                        } else {
                            (trimmed, true)
                        };
                        let mut captures =
                            parse_asm_pattern(stringify!(#struct_ident), #base_pattern, body)?;
                        #(#bindings)*
                        Ok(#construct)
                    }
                } else if normalized
                    .contains("let suffix = if *aq && *rl { \".aqrl\" } else if *aq { \".aq\" } else if *rl { \".rl\" } else { \"\" };")
                {
                    let format_str = self
                        .extract_format_string_from_rust_code(code)
                        .expect("aq/rl asm_code should contain format! string");
                    let base_pattern = strip_enc_suffixes_from_pattern(
                        &format_str.replace("{suffix}", ""),
                    );
                    let mnemonic = instruction.name.clone();
                    let bindings: Vec<_> = instruction
                        .operands
                        .iter()
                        .map(|operand| {
                            let operand_ident = Ident::new(&operand.name, Span::call_site());
                            let operand_name = operand.name.clone();
                            match operand.name.as_str() {
                                "aq" => quote! { let #operand_ident = aq; },
                                "rl" => quote! { let #operand_ident = rl; },
                                _ => {
                                    let operand_type: TokenStream = self
                                        .operand_to_typed_struct(operand, isa_base, instruction)
                                        .parse()
                                        .expect("Failed to parse operand type string");
                                    quote! {
                                        let #operand_ident = {
                                            let text = captures.remove(#operand_name).ok_or_else(|| {
                                                AsmParseError::syntax_mismatch(
                                                    stringify!(#struct_ident),
                                                    format!("missing operand `{}`", #operand_name),
                                                )
                                            })?;
                                            <#operand_type as AsmDecode>::decode_asm(&text)
                                                .map_err(|err| err.with_context(format!("while parsing operand `{}`", #operand_name)))?
                                        };
                                    }
                                }
                            }
                        })
                        .collect();
                    quote! {
                        let trimmed = s.trim();
                        let (rest, aq, rl) = if let Some(rest) = trimmed.strip_prefix(concat!(#mnemonic, ".aqrl")) {
                            (rest, true, true)
                        } else if let Some(rest) = trimmed.strip_prefix(concat!(#mnemonic, ".aq")) {
                            (rest, true, false)
                        } else if let Some(rest) = trimmed.strip_prefix(concat!(#mnemonic, ".rl")) {
                            (rest, false, true)
                        } else if let Some(rest) = trimmed.strip_prefix(#mnemonic) {
                            (rest, false, false)
                        } else {
                            let actual = asm_first_token(trimmed).unwrap_or(trimmed);
                            return Err(AsmParseError::mnemonic_mismatch(
                                stringify!(#struct_ident),
                                #mnemonic,
                                actual,
                            ));
                        };
                        let normalized = format!("{}{}", #mnemonic, rest);
                        let mut captures = parse_asm_pattern(
                            stringify!(#struct_ident),
                            #base_pattern,
                            &normalized,
                        )?;
                        #(#bindings)*
                        Ok(#construct)
                    }
                } else if normalized.contains("get_saved_reg_list_string()")
                    && normalized.contains("get_stack_adjustment()")
                {
                    let mnemonic = instruction.name.clone();
                    let field_ident = Ident::new(&instruction.operands[0].name, Span::call_site());
                    let field_type: TokenStream = self
                        .operand_to_typed_struct(&instruction.operands[0], isa_base, instruction)
                        .parse()
                        .expect("Failed to parse operand type string");
                    let stack_value = if instruction.name == "cm.push" {
                        quote! {
                            let printed_stack_adj = parse_asm_i64_literal(stack_adj_text)?;
                            printed_stack_adj.checked_neg().ok_or_else(|| {
                                AsmParseError::invalid_operand(
                                    stringify!(#struct_ident),
                                    format!("expected negative stack adjustment in `{}`", s.trim()),
                                )
                            })?
                        }
                    } else {
                        quote! { parse_asm_i64_literal(stack_adj_text)? }
                    };
                    quote! {
                        let trimmed = s.trim();
                        let rest = trimmed
                            .strip_prefix(concat!(#mnemonic, " "))
                            .ok_or_else(|| {
                                let actual = asm_first_token(trimmed).unwrap_or(trimmed);
                                AsmParseError::mnemonic_mismatch(
                                    stringify!(#struct_ident),
                                    #mnemonic,
                                    actual,
                                )
                            })?;
                        let (reg_list_text, stack_adj_text) = rest.rsplit_once(',').ok_or_else(|| {
                            AsmParseError::syntax_mismatch(
                                stringify!(#struct_ident),
                                format!("expected register list and stack adjustment in `{}`", trimmed),
                            )
                        })?;
                        let stack_adj = { #stack_value };
                        let #field_ident = <#field_type>::parse_display_parts(reg_list_text, stack_adj)?;
                        Ok(#construct)
                    }
                } else if instruction.name == "c.lui" {
                    let bindings: Vec<_> = instruction
                        .operands
                        .iter()
                        .map(|operand| {
                            let operand_ident = Ident::new(&operand.name, Span::call_site());
                            let operand_name = operand.name.clone();
                            let operand_type: TokenStream = self
                                .operand_to_typed_struct(operand, isa_base, instruction)
                                .parse()
                                .expect("Failed to parse operand type string");
                            if operand.name == "imm" {
                                quote! {
                                    let #operand_ident = {
                                        let text = captures.remove(#operand_name).ok_or_else(|| {
                                            AsmParseError::syntax_mismatch(
                                                stringify!(#struct_ident),
                                                "missing operand `imm`",
                                            )
                                        })?;
                                        let sign_extended = parse_asm_sign_extended_literal(&text, 20)?;
                                        <#operand_type as AsmDecode>::decode_asm(
                                            &sign_extended.to_string(),
                                        )
                                        .map_err(|err| err.with_context("while parsing operand `imm`"))?
                                    };
                                }
                            } else {
                                quote! {
                                    let #operand_ident = {
                                        let text = captures.remove(#operand_name).ok_or_else(|| {
                                            AsmParseError::syntax_mismatch(
                                                stringify!(#struct_ident),
                                                format!("missing operand `{}`", #operand_name),
                                            )
                                        })?;
                                        <#operand_type as AsmDecode>::decode_asm(&text)
                                            .map_err(|err| err.with_context(format!("while parsing operand `{}`", #operand_name)))?
                                    };
                                }
                            }
                        })
                        .collect();
                    quote! {
                        let mut captures =
                            parse_asm_pattern(stringify!(#struct_ident), "c.lui {xd}, {imm}", s)?;
                        #(#bindings)*
                        Ok(#construct)
                    }
                } else if let Some(format_str) = self.extract_format_string_from_rust_code(code) {
                    let normalized_pattern = strip_enc_suffixes_from_pattern(&format_str);
                    let bindings = self.generate_standard_operand_bindings(
                        struct_ident,
                        instruction,
                        isa_base,
                        &normalized_pattern,
                    );
                    quote! {
                        let mut captures =
                            parse_asm_pattern(stringify!(#struct_ident), #normalized_pattern, s)?;
                        #(#bindings)*
                        Ok(#construct)
                    }
                } else {
                    panic!(
                        "unsupported asm_code parser generation for instruction {}",
                        instruction.name
                    );
                }
            }
        };

        quote! {
            impl AsmDecode for #struct_ident {
                fn decode_asm(s: &str) -> Result<Self, AsmParseError> {
                    #body
                }
            }

            impl std::str::FromStr for #struct_ident {
                type Err = AsmParseError;
                fn from_str(s: &str) -> Result<Self, Self::Err> {
                    <Self as AsmDecode>::decode_asm(s)
                }
            }
        }
    }

    fn generate_instruction_struct_definition(
        &self,
        struct_ident: &Ident,
        doc_comment: &str,
        instruction: &Instruction,
        isa_base: &ISABase,
    ) -> TokenStream {
        let attribute_token = self.generate_attribute_token(&instruction.assembly_syntax);
        let sequence_attribute = self.generate_sequence_attribute(instruction);

        if instruction.operands.is_empty() {
            return quote! {
                #[doc = #doc_comment]
                #[derive(Debug, Clone, PartialEq, Serialize, Deserialize, DeriveInstructionDisplay, DeriveRandom)]
                #sequence_attribute
                #attribute_token
                pub struct #struct_ident;
            };
        }

        let fields = self.generate_instruction_fields(instruction, isa_base);
        quote! {
            #[doc = #doc_comment]
            #[derive(Debug, Clone, PartialEq, Serialize, Deserialize, DeriveInstructionDisplay, DeriveRandom)]
            #sequence_attribute
            #attribute_token
            pub struct #struct_ident {
                #(#fields),*
            }
        }
    }

    /// Generate instruction structs for separated mode.
    pub fn generate_separated_instruction_structs(&self) -> TokenStream {
        let mut all_structs = TokenStream::new();
        let mut by_extension_and_isa: HashMap<(ISAExtension, ISABase), Vec<&Instruction>> =
            HashMap::new();

        // Group by extension and ISA base.
        for inst in &self.instructions {
            for &isa_base in &inst.isa_bases {
                by_extension_and_isa
                    .entry((inst.extension.clone(), isa_base))
                    .or_default()
                    .push(inst);
            }
        }

        let mut processed_instructions = HashSet::new();

        for ((extension, isa_base), instructions) in by_extension_and_isa {
            for inst in instructions {
                let struct_name = format!(
                    "{}_{}_{}",
                    isa_base,
                    self.extension_identifier_fragment(&extension),
                    self.instruction_name_to_variant(&inst.name)
                );

                if processed_instructions.contains(&struct_name) {
                    continue;
                }
                processed_instructions.insert(struct_name.clone());

                let struct_ident = Ident::new(&struct_name, Span::call_site());
                let doc_comment = format!("{} {} instruction: {}", isa_base, extension, inst.name);
                all_structs.extend(self.generate_instruction_struct_definition(
                    &struct_ident,
                    &doc_comment,
                    inst,
                    &isa_base,
                ));
                all_structs.extend(self.generate_struct_from_str_impl(
                    &struct_ident,
                    inst,
                    &isa_base,
                ));
                all_structs.extend(self.generate_runtime_operand_access_impl(
                    &struct_ident,
                    inst,
                    &isa_base,
                ));
                all_structs.extend(self.generate_numeric_mutation_impl(&struct_ident, inst));
                if let Some(memory_access_impl) =
                    self.generate_memory_access_impl(&struct_ident, inst)
                {
                    all_structs.extend(memory_access_impl);
                }
            }
        }

        all_structs
    }
}
